import LegalPage from '../components/LegalPage'
import blocks from '../content/legal/privacy-policy'
import { seoFor } from '../seo/pages'

/**
 * /privacy-policy/ -- footer-linked, indexed, in the sitemap.
 *
 * NO GENERATED MARKER, DELIBERATELY. scripts/gen-pages.mjs overwrites any page
 * file still carrying `// GENERATED by scripts/gen-pages.mjs`, so re-adding
 * that line would replace this page with a PagePlaceholder stub on the next
 * `npm run gen:pages`.
 *
 * The body is VERBATIM legal text from the capture, parsed by
 * scripts/gen-legal.mjs into src/content/legal/privacy-policy.ts. Do not edit
 * the copy here or there -- regenerate it.
 *
 * The h1 is read from the PageSeo record rather than written as a literal so
 * it cannot drift from the captured page, the same call contact-us.tsx and
 * our-blogs.tsx make.
 */
export default function PrivacyPolicy() {
  return (
    <LegalPage
      title={seoFor('privacy-policy').h1 ?? 'Privacy Policy'}
      crumb="Privacy Policy"
      blocks={blocks}
    />
  )
}
